<!doctype html><html lang="{{ app()->getLocale() }}" dir="{{ in_array(app()->getLocale(),['ar','he'],true)?'rtl':'ltr' }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مقارنة العقارات | Ozman</title><meta name="robots" content="noindex, follow"><style>*{box-sizing:border-box}body{margin:0;background:#071018;color:#f7fbff;font-family:Arial,Tahoma,sans-serif}.wrap{width:min(1200px,calc(100% - 28px));margin:auto;padding:30px 0}a{color:#18d9f3}.table-wrap{overflow:auto;border:1px solid #263a48;border-radius:18px}table{width:100%;min-width:700px;border-collapse:collapse;background:#101b25}th,td{padding:15px;border-bottom:1px solid #263a48;text-align:center}th:first-child,td:first-child{position:sticky;right:0;background:#0b151d;text-align:right}img,.placeholder{display:grid;place-items:center;width:180px;height:130px;margin:auto;object-fit:cover;border-radius:12px;background:#172631}.price{color:#18d9f3;font-weight:900}.empty{padding:70px;text-align:center}</style></head><body><main class="wrap"><a href="{{ url()->previous() }}">← العودة</a><h1>مقارنة العقارات</h1>@if($properties->isEmpty())<div class="empty">اختر عقارين على الأقل من صفحة البحث للمقارنة.</div>@else<div class="table-wrap"><table><thead><tr><th>المواصفة</th>@foreach($properties as $property)<th><a href="{{ $property->publicUrl() }}">{{ $property->localized('title') }}</a></th>@endforeach</tr></thead><tbody><tr><td>الصورة</td>@foreach($properties as $property)<td>@if($property->images->first())<img src="{{ asset($property->images->first()->path) }}" alt="{{ $property->localized('title') }}">@else<div class="placeholder">لا توجد صورة</div>@endif</td>@endforeach</tr>@foreach(['price'=>'السعر','purpose'=>'بيع / إيجار','property_type'=>'النوع','city'=>'المدينة','neighborhood'=>'المنطقة','area'=>'المساحة م²','rooms'=>'الغرف','bathrooms'=>'الحمامات','floor'=>'الطابق','parking_spaces'=>'المواقف','furnished'=>'مفروش','has_elevator'=>'مصعد','has_balcony'=>'شرفة','has_garden'=>'حديقة','has_storage'=>'مخزن','has_air_conditioning'=>'تكييف'] as $field=>$label)<tr><td>{{ $label }}</td>@foreach($properties as $property)<td @class(['price'=>$field==='price'])>@if($field==='price'){{ number_format((float)$property->price) }} {{ $property->currency }}@elseif(in_array($field,['furnished','has_elevator','has_balcony','has_garden','has_storage','has_air_conditioning'],true)){{ $property->{$field}?'✓':'—' }}@elseif($field==='purpose'){{ $property->purpose==='rent'?'إيجار':'بيع' }}@else{{ $property->{$field}??'—' }}@endif</td>@endforeach</tr>@endforeach</tbody></table></div>@endif</main></body></html>
